// Deictic page/document references, not every occurrence of “document” or “page”.
export function pageIntent(text){const t=String(text).replace(/[’]/g,"'").trim();
 // References to visible text trigger a real read, never a screen-vision claim.
 if(/\b(?:question|problem|error|code|paragraph|option)\b.{0,55}\b(?:on (?:my|the) screen|on the page|I(?:'m| am) looking at|in (?:this|the) (?:page|tab))\b/i.test(t))return true;
 if(/\b(?:question|problem|number|#)\s*\d{1,3}\b|\b(?:last|final) question\b/i.test(t))return true;
 if(/^(?:what(?:'s| is) (?:the answer|number \d+|this question(?: asking)?|the main idea)|solve (?:this|the problem I'm looking at)|explain this (?:problem|code|error)|what does this (?:mean|error mean)|summarize what I(?:'m| am) reading|which (?:answer|option) is (?:correct|right|best)|help me understand this|what should I (?:write|do next)|why (?:isn't|is not) this working|which prototype should (?:I|we|the company) (?:choose|buy|select))(?:[.!?]|$)/i.test(t))return true;
 return /\b(?:this|current|active)\s+(?:web\s*)?(?:page|site|tab|article|document)\b|\b(?:the )?(?:page|article|document|website)\s+(?:that )?I(?:'m| am)\s+(?:currently\s+)?(?:viewing|reading|looking at)|\bwhat (?:am I looking at|I(?:'m| am) reading)|\b(?:first|second|third|fourth|fifth)\s+(?:main\s+)?paragraph|\b(?:selected|highlighted) text|\b(?:this|the) paragraph|\b(?:the|this) author|\bthese sections/i.test(t)||/^(?:read this|summarize this|explain this|what(?:'s| is) this)[.!?]*$/i.test(t);
}
export function pagePermission(settings){if(settings.privateSession)return 'Page sharing is unavailable in Private mode. Use a normal session to share readable webpage text.';if(!settings.cloudAI)return 'Cloud AI is turned off. Enable Allow cloud AI in PoxeyX1 Settings before sharing page text.';if(!settings.pageAI)return "Page sharing is turned off. Please enable Share active-page text in PoxeyX1 Settings.";return null;}
export const relatedFollowUp=text=>/^(?:why(?:\s|\?)|how so|how much (?:cheaper|more|less|budget|money|does (?:it|that)|is (?:it|that))|what about|which one|explain (?:that|it)|make (?:that|it)|summarize (?:that|it)|tell me more|what does that)/i.test(text.trim());
// A reference to the user's open writing is not an ordinary general-knowledge
// question. It requires excerpt approval or the separate automatic-document opt-in.

